// Text for the WS3 comparison: the shipped detector against the false-alarm controls, on the same
// fixtures. renderControlsTable goes to the console; renderControlsReport is docs/agents/ws3-eval-report.md
// (generated: do not edit by hand).

import { SENSITIVITIES } from './evaluate.mjs';

const pct = v => (v === null ? 'n/a' : v.toFixed(2));
const row = (rows, behavior = 'nail_biting') => rows.find(r => r.behavior === behavior);
const sign = n => (n > 0 ? `+${n}` : String(n));

function falseAlarmsIn(result, behavior = 'nail_biting', graceMs = 1000) {
  const { fixture, alarms } = result;
  return alarms.filter(a => !fixture.labels.some(l => l.behaviors.includes(behavior) && a.t >= l.startMs && a.t <= l.endMs + graceMs)).length;
}

export function renderControlsTable(result) {
  const { thresholds, bySensitivity, controls, learning, acceptance } = result;
  const g = thresholds.gateSensitivity;
  const s = row(bySensitivity[g]);
  const c = row(controls[g]);
  const l = row(learning[g]);
  const lines = [];
  lines.push('', `False-alarm controls (the false_positive_controls flag), nail_biting at ${g} sensitivity, same fixtures:`);
  lines.push(`  shipped    precision ${pct(s.precision)}  recall ${pct(s.recall)}  alarms ok/false ${s.correct}/${s.falseAlarms}  events found ${s.detected}/${s.events}`);
  lines.push(`  controls   precision ${pct(c.precision)}  recall ${pct(c.recall)}  alarms ok/false ${c.correct}/${c.falseAlarms}  events found ${c.detected}/${c.events}   bar ${c.bar.minPrecision}/${c.bar.minRecall}`);
  lines.push(`  learning, sequences (a pose rejected five times, then a real bite): ${l.correct} of ${l.events} bites found, ${l.falseAlarms} false alarms (${l.taps} taps); shipped: ${result.sequenceShipped[g].reduce((n, r) => n + r.alarms.length, 0) - l.correct} false`);
  lines.push(`  chin-rest-rule fixtures: false alarms ${acceptance.chinRest.before} shipped -> ${acceptance.chinRest.after} with the controls`);
  return lines.join('\n');
}

export function renderControlsReport(result) {
  const { thresholds, allFixtures, fixtures, sequences, bySensitivity, controls, learning, acceptance, verdict } = result;
  const g = thresholds.gateSensitivity;
  const graceMs = thresholds.graceMs ?? 1000;
  const out = [];
  const w = line => out.push(line);

  w('# WS3 evaluation: fewer false alarms');
  w('');
  w('> **SYNTHETIC. This is not real-world accuracy.**');
  w(`> ${allFixtures.length} landmark fixtures drawn by the same person who wrote the controls (a neutral stick-model face and hand, `
    + '`scripts/eval-detection/generate-fixtures.mjs`). The chin-rest scenes were drawn to match the rule, so the controls doing well on them shows the rule fires where it was meant to and costs nothing on the synthetic bites. '
    + 'It does not show that real chins, real knuckles or real cameras behave this way. Do not quote these numbers anywhere.');
  w('');
  w('Generated by `npm run eval:detection -- --controls-report docs/agents/ws3-eval-report.md`. Do not edit by hand; regenerate it.');
  w('');
  w('## What is compared');
  w('');
  w('- **shipped**: the detector with the `false_positive_controls` flag OFF. Its decisions are pinned frame by frame against the pre-WS1 code (`src/detection/equivalence.test.ts`).');
  w('- **controls**: the flag ON for a person who has not yet tapped "Not a bite": both hands, and the chin-rest rule (the back of the hand, the knuckles or the palm on the chin, and no fingertip within 0.15 face widths of the lips: do not fire).');
  w('- **learning**: the flag ON and a simulated person who taps "Not a bite" after every false alarm (judged by the fixture\'s own labels). Each tap remembers six pose numbers; two like rejections make that pose need a fingertip within 0.2 face widths of the lips. Only the `sequence` fixtures (below) use it: a single scene has no second visit to learn from.');
  w(`- ${fixtures.length} single-scene fixtures give the headline numbers for shipped and controls; ${sequences.length} sequence fixtures (one pose five times, then a real bite) are scored apart, so they cannot move the shipped bar.`);
  w(`- Scoring is the harness's: an alarm is *correct* inside a labelled event (up to ${graceMs} ms after it ends), otherwise *false*; an event is *found* by one correct alarm. Precision = correct / all alarms, recall = events found / all events.`);
  w('');

  w(`## nail_biting at ${g} sensitivity (the gate), single scenes`);
  w('');
  w('| Variant | Precision | Recall | Alarms (ok / false) | Events (found / all) | Bar (P / R) |');
  w('|---|---|---|---|---|---|');
  const s = row(bySensitivity[g]);
  const c = row(controls[g]);
  w(`| shipped | ${pct(s.precision)} | ${pct(s.recall)} | ${s.correct} / ${s.falseAlarms} | ${s.detected} / ${s.events} | ${s.bar.minPrecision} / ${s.bar.minRecall} |`);
  w(`| controls | ${pct(c.precision)} | ${pct(c.recall)} | ${c.correct} / ${c.falseAlarms} | ${c.detected} / ${c.events} | ${c.bar.minPrecision} / ${c.bar.minRecall} |`);
  w('');
  w(`False alarms ${s.falseAlarms} -> ${c.falseAlarms} (${sign(c.falseAlarms - s.falseAlarms)}); events found ${s.detected}/${s.events} -> ${c.detected}/${c.events}. `
    + 'The cuticle/skin-biting rule is the same mouth rule under another name and scores the same.');
  w('');
  w('The ratchet: the `withControls` bar in `scripts/eval-detection/thresholds.json` is set just under the precision measured here. Raise it when the controls improve; never lower it to make a change pass.');
  w('');

  w('## All sensitivities (nail_biting, single scenes)');
  w('');
  w('| Sensitivity | shipped P / R (ok-false) | controls P / R (ok-false) |');
  w('|---|---|---|');
  for (const sens of SENSITIVITIES) {
    const a = row(bySensitivity[sens]);
    const b = row(controls[sens]);
    w(`| ${sens}${sens === g ? ' (gate)' : ''} | ${pct(a.precision)} / ${pct(a.recall)} (${a.correct}-${a.falseAlarms}) | ${pct(b.precision)} / ${pct(b.recall)} (${b.correct}-${b.falseAlarms}) |`);
  }
  w('');

  w(`## Chin-rest scenes (${g})`);
  w('');
  w('False alarms per fixture, shipped against controls. `rule` marks the scenes drawn to match the chin-rest rule (knuckles on the chin, no fingertip near the lips).');
  w('');
  w('| Fixture | rule | shipped | controls | |');
  w('|---|---|---|---|---|');
  const sRows = row(bySensitivity[g]).results;
  const cRows = row(controls[g]).results;
  for (const sr of sRows) {
    if (!(sr.fixture.tags.includes('chin-rest') || sr.fixture.tags.includes('chin-rest-rule'))) continue;
    const cr = cRows.find(x => x.fixture.id === sr.fixture.id);
    const before = falseAlarmsIn(sr, 'nail_biting', graceMs);
    const after = falseAlarmsIn(cr, 'nail_biting', graceMs);
    const note = after < before ? 'fixed' : before === 0 && after === 0 ? 'quiet' : 'NOT changed';
    w(`| \`${sr.fixture.id}\` | ${sr.fixture.tags.includes('chin-rest-rule') ? 'yes' : 'no'} | ${before} | ${after} | ${note} |`);
  }
  w('');
  w(`On the \`chin-rest-rule\` scenes: ${acceptance.chinRest.before} false alarms shipped, ${acceptance.chinRest.after} with the controls. `
    + '**The two older chin-rest scenes (`neg_chin_rest`, `neg_cheek_rest_thinking`) are NOT changed**: they are drawn with the fingers along the jaw and the palm far from the chin, so the literal rule (palm or knuckles on the chin) does not apply to them. '
    + 'They are the poses the learning is for.');
  w('');

  const changed = sRows.filter(sr => {
    if (sr.fixture.tags.includes('chin-rest') || sr.fixture.tags.includes('chin-rest-rule')) return false;
    const cr = cRows.find(x => x.fixture.id === sr.fixture.id);
    return falseAlarmsIn(sr, 'nail_biting', graceMs) !== falseAlarmsIn(cr, 'nail_biting', graceMs);
  });
  w(`## Any other scene whose false alarms changed (${g})`);
  w('');
  if (changed.length === 0) {
    w('None.');
  } else {
    for (const sr of changed) {
      const cr = cRows.find(x => x.fixture.id === sr.fixture.id);
      w(`- \`${sr.fixture.id}\`: ${falseAlarmsIn(sr, 'nail_biting', graceMs)} -> ${falseAlarmsIn(cr, 'nail_biting', graceMs)}. Not drawn for the chin-rest rule: the synthetic hand's wrist hangs near the chin while the curled fingers pass the lips, which the rule reads as a hand resting on the chin. An incidental effect of the drawing, not a result to build on.`);
    }
  }
  w('');

  w(`## Do the controls cost bites? (${g})`);
  w('');
  w('Every labelled bite, shipped against controls. The `near chin` scenes have the palm close to the chin with a fingertip at the lips: the case the rule could kill.');
  w('');
  w('| Fixture | near chin | events | shipped found | controls found |');
  w('|---|---|---|---|---|');
  for (const sr of sRows) {
    const events = sr.fixture.labels.filter(l => l.behaviors.includes('nail_biting')).length;
    if (events === 0) continue;
    const cr = cRows.find(x => x.fixture.id === sr.fixture.id);
    const sf = foundIn(sr, graceMs);
    const cf = foundIn(cr, graceMs);
    w(`| \`${sr.fixture.id}\` | ${sr.fixture.tags.includes('hand-near-chin') ? 'yes' : ''} | ${events} | ${sf} | ${cf} |`);
  }
  w('');

  const more = sRows.filter(sr => {
    const cr = cRows.find(x => x.fixture.id === sr.fixture.id);
    return cr.alarms.length > sr.alarms.length;
  });
  const lowShipped = row(bySensitivity.low).results;
  const lowControls = row(controls.low).results;
  const moreAtLow = lowShipped.filter(sr => lowControls.find(x => x.fixture.id === sr.fixture.id).alarms.length > sr.alarms.length);
  w('## Where the controls make MORE alarms');
  w('');
  if (more.length === 0 && moreAtLow.length === 0) {
    w('Nowhere, at any sensitivity.');
  } else {
    w('A veto in the middle of a long hold ends the alarm, and when the hand then comes back to the lips a second alarm can start: one episode becomes two. The alarm time is shorter, but the count is higher.');
    w('');
    for (const sr of more) w(`- \`${sr.fixture.id}\` (${g}): ${sr.alarms.length} alarm(s) shipped, ${cRows.find(x => x.fixture.id === sr.fixture.id).alarms.length} with the controls.`);
    for (const sr of moreAtLow) w(`- \`${sr.fixture.id}\` (low): ${sr.alarms.length} alarm(s) shipped, ${lowControls.find(x => x.fixture.id === sr.fixture.id).alarms.length} with the controls.`);
  }
  w('');

  w(`## Learning from taps: a pose rejected five times, then a real bite (${g})`);
  w('');
  w('A simulated person taps "Not a bite" after every false alarm. The first rejections still sound (the app has to be told once or twice); once two like rejections are remembered, that pose needs a fingertip within 0.2 face widths of the lips.');
  w('');
  w('| Fixture | false alarms shipped | false alarms learning | taps | real bite found |');
  w('|---|---|---|---|---|');
  const lRows = row(learning[g]).results;
  for (const lr of lRows) {
    const sr = sequenceShipped(result, lr.fixture.id, g);
    w(`| \`${lr.fixture.id}\` | ${falseAlarmsIn(sr, 'nail_biting', graceMs)} | ${falseAlarmsIn(lr, 'nail_biting', graceMs)} | ${lr.taps} | ${foundIn(lr, graceMs) > 0 ? 'yes' : '**NO**'} |`);
  }
  w('');
  const l = row(learning[g]);
  w(`Over the sequences: precision ${pct(l.precision)}, recall ${pct(l.recall)} (${l.detected}/${l.events} bites found).`);
  w('');

  w('## The bars');
  w('');
  w('| Run | Level | Precision | Recall | Status |');
  w('|---|---|---|---|---|');
  for (const [label, rows] of [['shipped', bySensitivity[g]], ['controls', controls[g]], ['learning (sequences)', learning[g]]]) {
    const r = row(rows);
    w(`| ${label} | validated | ${pct(r.precision)} (bar ${r.bar.minPrecision}) | ${pct(r.recall)} (bar ${r.bar.minRecall}) | ${r.passesBar ? 'PASS' : 'FAIL'} |`);
  }
  w('');
  w(verdict.ok ? '**Gate: every bar is met, recall with the controls is within 5 points of the shipped detector\'s, and the chin-rest-rule scenes have fewer false alarms.**' : `**Gate: FAILED.** ${verdict.failures.join('; ')}`);
  w('');
  return out.join('\n');
}

function foundIn(result, graceMs) {
  const mine = result.fixture.labels.filter(l => l.behaviors.includes('nail_biting'));
  return mine.filter(l => result.alarms.some(a => a.t >= l.startMs && a.t <= l.endMs + graceMs)).length;
}

function sequenceShipped(result, id, g) {
  // The sequences are replayed once without controls for the comparison column.
  return result.sequenceShipped[g].find(x => x.fixture.id === id);
}
